<script setup lang="ts">
import {ref} from 'vue'
import PageShell from '../../../components/PageShell.vue'
import AppIcon from '../../../components/AppIcon.vue'
import HealthCard from '../../../components/HealthCard.vue'
import StatePanel from '../../../components/StatePanel.vue'
import {reportsApi} from '../../../api/reports'
import type {ReportListItem} from '../../../types/report-list'
import {healthApi} from '../../../api/health'
import {useUserStore} from '../../../stores/user'
import {usePageData} from '../../../utils/usePageData'
import {go} from '../../../utils/navigation'
import type {Archive,Article,Notice} from '../../../types'
const store=useUserStore(),archive=ref<Archive>(),articles=ref<Article[]>([]),notices=ref<Notice[]>([])
const latestUpload=ref<ReportListItem>(),listError=ref('')
const {loading,error,load}=usePageData('worker',async()=>{const [health,list]=await Promise.allSettled([healthApi.archive(),reportsApi.paginatedList('all',1,10)]);if(health.status==='fulfilled')archive.value=health.value;latestUpload.value=list.status==='fulfilled'?list.value.items[0]:undefined;listError.value=list.status==='rejected'?'报告列表加载失败':'';articles.value=[];notices.value=[];if(health.status==='rejected')throw health.reason})
const shortcuts=[{title:'体检报告',icon:'file-text',url:'reports',tone:'green'},{title:'健康档案',icon:'folder-heart',url:'archive',tone:'green'},{title:'AI助手',icon:'bot',url:'assistant',tone:'teal'},{title:'健康建议',icon:'heart-pulse',url:'advice',tone:'orange'},{title:'复查提醒',icon:'calendar-check',url:'followups',tone:'green'},{title:'职业防护',icon:'shield-check',url:'knowledge',tone:'blue'},{title:'健康趋势',icon:'chart-no-axes-combined',url:'archive?trend=1',tone:'blue'},{title:'应急联系',icon:'phone',url:'emergency',tone:'orange'}]
function shortcut(url:string){if(url==='emergency'){uni.showModal({title:'应急联系',content:'如遇紧急情况，请使用当地急救服务或矿区应急调度电话。企业调度电话待管理员配置。',confirmText:'拨打120',cancelText:'关闭',success:r=>{if(r.confirm)uni.makePhoneCall({phoneNumber:'120'})}});return}const [path,query]=url.split('?');go('/pages/worker/'+path+'/index'+(query?'?'+query:''))}
</script>
<template><PageShell title="矿安智康" tab="home" :back="false" hero><view class="home-hero"><image class="hero-mine" src="/static/mine-scene.png" mode="aspectFill"/><view class="greeting"><image class="avatar" src="/static/miner.png"/><view class="grow"><text class="greeting-name">您好，{{store.profile?.name||'师傅'}}</text><text class="greeting-meta">{{store.profile?.employeeNo}} <text class="separator">|</text> {{store.profile?.department}}</text></view><view class="notification" @tap="go('/pages/worker/notifications/index')"><AppIcon name="bell" color="white" :size="24"/><view v-if="notices.length" class="notice-dot"/></view></view><view class="hero-slogan">每一份辛勤，都值得被健康守护</view></view><view class="content home-content"><StatePanel :error="error" :loading="loading" @retry="load"/><HealthCard v-if="archive" :report="archive.reports[0]" :latest-upload="latestUpload" :list-error="listError"/><view class="card shortcut-card"><view v-for="item in shortcuts" :key="item.title" class="shortcut" @tap="shortcut(item.url)"><view class="shortcut-icon" :class="item.tone"><AppIcon :name="item.icon" :size="27"/></view><text>{{item.title}}</text></view></view><view class="card notice-card" @tap="go('/pages/worker/notifications/index')"><view class="section-head"><view class="flex gap"><AppIcon name="megaphone" :size="18"/><text class="section-title">最新通知</text></view><text class="more">全部 ›</text></view><view v-if="notices[0]" class="notice-text"><text>{{notices[0].title}}</text><text class="caption muted">今天</text></view><text v-else class="help">消息服务尚未接入</text></view><view v-if="articles.length" class="section-head knowledge-heading"><text class="section-title">健康，一点点了解</text><text class="more" @tap="go('/pages/worker/knowledge/index')">更多科普 ›</text></view><view class="card article-home" v-for="(article,i) in articles.slice(0,2)" :key="article.id" @tap="go('/pages/worker/knowledge/index?id='+article.id)"><view class="article-art" :class="{mint:i===1}"><AppIcon :name="i===0?'hard-hat':'clipboard-plus'" :size="38"/></view><view class="grow"><text class="article-category">{{article.category}}</text><text class="article-title">{{article.title}}</text><text class="article-summary">{{article.summary}}</text></view><AppIcon name="chevron-right" color="gray" :size="15"/></view><view class="home-end">安心工作，健康生活</view></view></PageShell></template>
<style scoped>.home-hero{height:270rpx;background:linear-gradient(110deg,#008b51,#00a064);position:relative;color:white;overflow:hidden;border-radius:0 0 42rpx 42rpx}.hero-mine{position:absolute;width:470rpx;height:240rpx;right:-70rpx;bottom:-75rpx;opacity:.15}.greeting{position:relative;display:flex;gap:20rpx;align-items:center;padding:32rpx 36rpx 8rpx}.avatar{border:3rpx solid #ffffff60}.greeting-name{font-size:37rpx;font-weight:650;display:block}.greeting-meta{font-size:23rpx;opacity:.82;display:block;margin-top:10rpx}.separator{padding:0 10rpx;opacity:.4}.hero-slogan{position:relative;font-size:21rpx;letter-spacing:2rpx;margin:10rpx 36rpx;opacity:.7}.notification{position:relative;padding:14rpx;background:#ffffff16;border-radius:20rpx}.notice-dot{position:absolute;right:13rpx;top:11rpx;width:12rpx;height:12rpx;border-radius:50%;background:#ffbd7a;border:2rpx solid #008d55}.home-content{position:relative;margin-top:-58rpx}.shortcut-card{display:flex;flex-wrap:wrap;padding:16rpx 10rpx 24rpx}.shortcut{width:25%;display:flex;flex-direction:column;align-items:center;gap:14rpx;font-size:24rpx;padding-top:20rpx;font-weight:500}.shortcut-icon{display:flex;padding:20rpx;border-radius:23rpx;background:#ecf8ef}.shortcut-icon.teal{background:#eaf8f5}.shortcut-icon.orange{background:#fff3e8}.shortcut-icon.blue{background:#ecf4f8}.notice-card{padding:25rpx 28rpx}.notice-card .section-title{font-size:27rpx}.notice-text{display:flex;justify-content:space-between;gap:16rpx;font-size:25rpx;margin-top:18rpx}.knowledge-heading{padding:12rpx 2rpx 18rpx}.article-home{display:flex;align-items:center;gap:20rpx;padding:22rpx;margin-bottom:16rpx}.article-art{background:#f0eee0;width:112rpx;height:126rpx;border-radius:17rpx;display:flex;align-items:center;justify-content:center;flex-shrink:0}.article-art.mint{background:#e5f0ed}.article-category{font-size:19rpx;color:#7c9b82;display:block}.article-title{font-size:27rpx;font-weight:600;display:block;margin:5rpx 0}.article-summary{font-size:21rpx;color:#8d9a90;display:-webkit-box;-webkit-line-clamp:1;-webkit-box-orient:vertical;overflow:hidden}.home-end{text-align:center;color:#adc0b1;font-size:21rpx;letter-spacing:5rpx;padding-top:25rpx}</style>
